INSERT INTO `categories` VALUES (1,'Ống kính Zoom Chuẩn (Standard Zoom)','Ống kính đa dụng dải tiêu cự 24-70mm, 28-75mm phục vụ chụp sự kiện, phóng sự cưới, chân dung và phong cảnh du lịch hàng ngày.','2026-08-15 00:33:07','2026-08-15 00:33:07'),(2,'Ống kính Chân Dung & Tiêu Cự Cố Định (Prime Lens)','Ống kính một tiêu cự khẩu độ cực lớn f/1.2 - f/1.8 mang lại độ sắc nét quang học tối đa và hiệu ứng xóa phông bokeh nghệ thuật.','2026-08-15 00:33:07','2026-08-15 00:33:07'),(3,'Ống kính Góc Siêu Rộng (Ultra-Wide Angle)','Dải tiêu cự từ 14mm đến 24mm mở rộng góc nhìn bao quát, chuyên dùng cho chụp phong cảnh thiên nhiên, kiến trúc và nội thất.','2026-08-15 00:33:07','2026-08-15 00:33:07'),(4,'Ống kính Siêu Tele (Telephoto Lens)','Ống kính tiêu cự xa từ 70-200mm đến 400mm bắt trọn chủ thể từ khoảng cách xa, chuyên cho thể thao, sân khấu và chim muông dã ngoại.','2026-08-15 00:33:07','2026-08-15 00:33:07'),(5,'Ống kính Chụp Cận Cảnh (Macro Lens)','Ống kính chuyên biệt với tỉ lệ phóng đại 1:1 hoặc lớn hơn, tái hiện siêu sắc nét các chi tiết tí hon, trang sức, hoa lá và côn trùng.','2026-08-15 00:33:07','2026-08-15 00:33:07'),(6,'Ống kính Quay Phim & Điện Ảnh (Cine Lens)','Ống kính điện ảnh chất lượng cao kiểm soát hiện tượng focus breathing, vòng lấy nét mượt mà dành cho các nhà làm phim chuyên nghiệp.','2026-08-15 00:33:07','2026-08-15 00:33:07');
/*!40000 ALTER TABLE `categories` ENABLE KEYS */;
