INSERT INTO `news` VALUES (1,'Canon RF 50mm f/1.2L USM — Tiêu chuẩn mới cho ống kính 50mm','Canon đã định nghĩa lại tiêu chuẩn cho ống kính tiêu cự chuẩn.','<p>Nội dung chi tiết về Canon RF 50mm f/1.2L USM...</p>','/storage/news/aHGcXkICWU3WUBXmHRqLHfmjG7kv1cn8Rx6339jj.webp','review','Review','Lê Hương',5,0,1,'2026-09-23 20:38:41','2026-09-23 23:14:47'),(4,'Sony FE 85mm f/1.4 GM II — Ống kính chân dung xuất sắc nhất 2026','Sony G Master 85mm f/1.4 GM II là bản nâng cấp vượt bậc so với thế hệ trước. Với hệ thống lấy nét XD Linear Motor cải tiến và khả năng bokeh ma thuật, đây là lựa chọn số 1 cho nhiếp ảnh chân dung.','<h2>Tổng quan về Sony FE 85mm f/1.4 GM II</h2>\n<p>Sony đã chính thức ra mắt phiên bản thứ hai của chiếc ống kính chân dung huyền thoại — FE 85mm f/1.4 GM. Sau nhiều năm chờ đợi, phiên bản mới này mang đến những cải tiến đáng kể cả về quang học lẫn cơ học, đặt ra một tiêu chuẩn mới cho dòng ống kính chân dung cao cấp.</p>\n<h2>Thiết kế và chất lượng xây dựng</h2>\n<p>Nhìn từ bên ngoài, Sony GM II 85mm vẫn giữ thiết kế quen thuộc của dòng G Master nhưng đã được tối ưu hóa đáng kể về trọng lượng. Ống kính nặng chỉ 700g, nhẹ hơn 14% so với phiên bản trước, giúp cho việc cầm nắm thoải mái hơn trong các buổi chụp dài.</p>\n<p>Vỏ ngoài được phủ lớp cao su chắc chắn với nhiều vị trí gioăng silicon chống bụi và thấm nước, đảm bảo an toàn cho ống kính trong mọi điều kiện thời tiết khắc nghiệt.</p>\n<h2>Hiệu suất lấy nét</h2>\n<p>Đây có lẽ là cải tiến ấn tượng nhất. Sony trang bị cho GM II hệ thống lấy nét XD Linear Motor thế hệ thứ ba với tốc độ nhanh gần gấp đôi so với người tiền nhiệm. Ống kính bắt nét tức thì, gần như không có tiếng ồn và hoàn toàn đáng tin cậy ngay cả với các chủ thể di chuyển nhanh.</p>\n<blockquote>Khi kết hợp với Sony A1 hoặc A9 III, khả năng tracking mắt đạt đến một tầm cao mới, gần như không bao giờ mất focus.</blockquote>\n<h2>Chất lượng quang học</h2>\n<p>Về mặt quang học, GM II 85mm tiếp tục sử dụng 11 thấu kính trong 8 nhóm với 1 thấu kính XA và 3 thấu kính ED. Kết hợp với lớp phủ Nano AR Coating II, ống kính xử lý flare và ghosting vượt trội ngay cả khi chụp ngược sáng mạnh.</p>\n<p>Bokeh ở f/1.4 đạt độ mềm mịn hiếm có, các điểm sáng được tái tạo thành những vòng tròn hoàn hảo không có viền cứng. Độ sắc nét trung tâm đạt đỉnh điểm ngay cả ở khẩu độ tối đa.</p>\n<h2>Kết luận</h2>\n<p>Sony FE 85mm f/1.4 GM II là một bước tiến thực sự đáng kể. Nếu bạn đang tìm kiếm ống kính chân dung tốt nhất cho hệ thống Sony, đây chắc chắn là lựa chọn không thể bỏ qua. Mức giá khoảng 65 triệu đồng khá cao nhưng xứng đáng với chất lượng vượt trội mà nó mang lại.</p>','https://images.unsplash.com/photo-1510127034890-ba27508e9f1c?w=1200&auto=format&fit=crop&q=80','review','Review','Nguyễn Minh Tuấn',12,0,1,'2026-09-23 23:28:40','2026-09-23 23:28:40'),(5,'Canon RF 50mm f/1.2L USM — Tiêu chuẩn mới cho ống kính 50mm','Canon đã định nghĩa lại tiêu chuẩn cho ống kính tiêu cự chuẩn với chiếc RF 50mm f/1.2L. Khẩu độ cực lớn, độ nét tuyệt vời và khả năng bokeh mê hoặc.','<h2>Giới thiệu Canon RF 50mm f/1.2L</h2>\r\n<p>Canon RF 50mm f/1.2L USM là một trong những ống kính ấn tượng nhất trong hệ sinh thái ngàm RF. Với khẩu độ f/1.2 hiếm có, Canon đã tạo ra một cỗ máy quang học thực thụ dành cho những nhiếp ảnh gia đòi hỏi chất lượng hình ảnh cao nhất.</p>\r\n<h2>Thiết kế và cảm giác cầm nắm</h2>\r\n<p>Ống kính có kích thước khá lớn với đường kính 85mm và chiều dài 108mm, nặng 950g. Dù nặng nhưng cân bằng tốt khi gắn trên các thân máy Canon R5 hay R6. Vòng điều khiển điện tử là điểm cộng lớn, cho phép điều chỉnh EV, ISO hoặc AF trực quan.</p>\r\n<h2>Chất lượng ảnh tại f/1.2</h2>\r\n<p>Điều đáng kinh ngạc nhất về RF 50mm f/1.2L là chất lượng ảnh ngay tại khẩu độ tối đa. Trong khi hầu hết các ống kính khẩu lớn thường mềm ở f/1.2, Canon đã làm được điều không tưởng: ảnh sắc nét đáng kể ngay tại f/1.2, đặc biệt ở vùng trung tâm.</p>\r\n<blockquote>Bokeh của RF 50mm f/1.2L có lẽ là đẹp nhất mình từng thấy ở một ống kính 50mm — mịn, không cứng viền, và tạo ra chiều sâu trường ảnh cực kỳ ấn tượng.</blockquote>\r\n<h2>Kết luận</h2>\r\n<p>Canon RF 50mm f/1.2L USM là một tuyệt tác công nghệ quang học. Nếu bạn sử dụng hệ thống Canon RF và cần ống kính chân dung hoặc phong cách sống đỉnh nhất, đây là câu trả lời. Mức giá khoảng 75 triệu đồng phản ánh đúng chất lượng vượt trội của nó.</p>','/storage/news/HVLAmb3C3X1UZtZrGxMgi2h1jSNlXYfriF1YFr47.webp','review','Review','Lê Hương',10,0,0,'2026-09-23 23:28:40','2026-09-23 23:35:48'),(6,'7 kỹ thuật bố cục ảnh đẹp mà mọi nhiếp ảnh gia cần biết','Bố cục là yếu tố quyết định một tấm ảnh có đẹp hay không. Khám phá 7 kỹ thuật bố cục cơ bản nhưng cực kỳ hiệu quả mà mọi nhiếp ảnh gia nên nắm vững.','<h2>Tại sao bố cục quan trọng?</h2>\n<p>Trong nhiếp ảnh, bố cục (composition) là cách bạn sắp xếp các yếu tố trong khung hình để tạo ra một bức ảnh hài hòa, thu hút ánh nhìn và truyền tải được thông điệp bạn muốn. Dù bạn có ống kính đắt tiền đến đâu, nếu bố cục kém thì ảnh vẫn kém hấp dẫn.</p>\n<h2>1. Quy tắc 1/3 (Rule of Thirds)</h2>\n<p>Đây là quy tắc bố cục cơ bản nhất. Chia khung hình thành 9 phần bằng nhau bởi 2 đường ngang và 2 đường dọc. Đặt chủ thể chính tại các điểm giao của những đường này thay vì ở chính giữa. Ảnh sẽ ngay lập tức trở nên năng động và thú vị hơn.</p>\n<h2>2. Đường dẫn (Leading Lines)</h2>\n<p>Sử dụng các đường tự nhiên trong cảnh — con đường, hàng cây, lan can, sóng biển — để dẫn dắt ánh mắt người xem vào chủ thể chính. Đây là kỹ thuật mạnh mẽ tạo chiều sâu và sự cuốn hút cho ảnh.</p>\n<h2>3. Đối xứng và phản chiếu</h2>\n<p>Bố cục đối xứng tạo ra cảm giác cân bằng, ổn định và thường rất đẹp mắt. Đặc biệt hiệu quả với kiến trúc, cảnh phản chiếu trên mặt nước, hay các khuôn mặt đối xứng trong ảnh chân dung.</p>\n<h2>4. Khung trong khung (Frame within Frame)</h2>\n<p>Dùng các yếu tố tự nhiên như cửa vòm, cành cây, cổng để \"đóng khung\" chủ thể. Kỹ thuật này tạo chiều sâu, thêm bối cảnh và hướng sự chú ý vào chủ thể một cách tự nhiên.</p>\n<h2>5. Quy tắc không gian (Negative Space)</h2>\n<p>Đừng sợ để nhiều khoảng trống trong ảnh. Khoảng trống (negative space) xung quanh chủ thể có thể tạo ra cảm giác cô đơn, trống vắng hoặc sự nhỏ bé của chủ thể so với thế giới xung quanh.</p>\n<h2>6. Màu sắc tương phản</h2>\n<p>Sử dụng màu sắc đối lập để làm nổi bật chủ thể. Một chiếc áo đỏ trên nền xanh lá, hay bầu trời xanh tương phản với hoàng hôn cam — màu sắc tương phản luôn tạo ra điểm nhấn mạnh mẽ.</p>\n<h2>7. Chiều sâu trường ảnh</h2>\n<p>Tạo ra cảm giác ba chiều bằng cách bao gồm các yếu tố ở tiền cảnh, chủ thể giữa và hậu cảnh. Điều này giúp ảnh có chiều sâu, thực tế hơn và kéo người xem vào trong khung hình.</p>\n<h2>Kết luận</h2>\n<p>Không có quy tắc nào là tuyệt đối trong nhiếp ảnh. Hãy nắm vững những nguyên tắc trên, sau đó học cách phá vỡ chúng một cách có chủ đích. Đó mới là con đường phát triển phong cách riêng của bạn.</p>','https://images.unsplash.com/photo-1542038784456-1ea8e935640e?w=1200&auto=format&fit=crop&q=80','tips','Mẹo','Phạm Minh',8,0,0,'2026-09-23 23:28:40','2026-09-23 23:28:40'),(7,'Sigma 35mm f/1.4 Art vs Sony FE 35mm f/1.4 GM — Ai thắng?','Hai ống kính 35mm đình đám nhất thị trường với mức giá cách nhau khá xa. Liệu Sigma Art có xứng đáng thách thức Sony G Master? Hãy cùng so sánh chi tiết.','<h2>Cuộc chiến ở tiêu cự 35mm</h2>\n<p>35mm là một trong những tiêu cự được ưa chuộng nhất trong nhiếp ảnh. Không quá rộng như góc rộng, không quá chật như tiêu cự chuẩn, 35mm là khoảng \"ngọt ngào\" cho nhiều thể loại: đường phố, chân dung môi trường, phong cảnh đô thị...</p>\n<h2>Sigma 35mm f/1.4 Art — Giá trị tuyệt vời</h2>\n<p>Sigma 35mm f/1.4 Art là một trong những ống kính nổi tiếng nhất của hãng. Ra mắt lần đầu năm 2012 nhưng vẫn cạnh tranh tốt cho đến ngày nay. Chất lượng quang học xuất sắc với độ nét cao ở trung tâm, xử lý aberration tốt và bokeh mịn màng đã khiến nó trở thành lựa chọn hàng đầu cho nhiều nhiếp ảnh gia tìm kiếm chất lượng cao với ngân sách hợp lý.</p>\n<h2>Sony FE 35mm f/1.4 GM — Đỉnh cao quang học</h2>\n<p>Sony ra mắt FE 35mm f/1.4 GM năm 2021, ngay lập tức trở thành chuẩn mực mới cho tiêu cự 35mm. Ống kính sử dụng cấu trúc quang học 14 thấu kính trong 10 nhóm, bao gồm 2 thấu kính XA và 2 thấu kính ED. Độ nét cạnh ảnh của GM 35mm vượt trội hơn hẳn so với Sigma, đặc biệt ở khẩu độ f/1.4.</p>\n<blockquote>Nếu bạn muốn \"best of the best\", Sony GM 35mm là câu trả lời. Nhưng nếu bạn muốn 90% chất lượng với 60% giá tiền, Sigma Art vẫn là một trong những ống kính tốt nhất từng được sản xuất.</blockquote>\n<h2>So sánh trực tiếp</h2>\n<p><strong>Độ nét:</strong> Sony GM thắng nhẹ ở cạnh ảnh, Sigma bắt kịp từ f/2.0<br>\n<strong>Bokeh:</strong> Sony GM đẹp hơn, mịn và ít cứng viền hơn<br>\n<strong>Lấy nét:</strong> Sony GM nhanh hơn và yên tĩnh hơn đáng kể<br>\n<strong>Trọng lượng:</strong> Sony GM 524g vs Sigma Art 665g — Sony nhẹ hơn nhiều<br>\n<strong>Giá:</strong> Sigma Art khoảng 16 triệu vs Sony GM khoảng 42 triệu</p>\n<h2>Kết luận</h2>\n<p>Cả hai đều là ống kính xuất sắc. Sigma Art dành cho những ai có ngân sách hạn chế nhưng không muốn hy sinh quá nhiều chất lượng. Sony GM dành cho những ai muốn điều tốt nhất và sẵn sàng chi trả cho nó.</p>','https://images.unsplash.com/photo-1493863641943-9b68992a8d07?w=1200&auto=format&fit=crop&q=80','compare','So sánh','Trần Quang',15,0,0,'2026-09-23 23:28:40','2026-09-23 23:28:40'),(8,'Nikon Z 135mm f/1.8 S Plena — Ống kính chân dung đáng mong đợi nhất năm','Nikon vừa ra mắt ống kính chân dung cao cấp nhất trong dòng Nikkor Z. Plena hứa hẹn mang đến bokeh hoàn hảo và độ nét siêu sắc.','<h2>Plena — Cái tên nói lên tất cả</h2>\r\n<p>\"Plena\" trong tiếng Latin có nghĩa là \"đầy đủ, hoàn hảo\". Và quả thực, Nikon đã đặt tên rất chính xác cho chiếc ống kính mới nhất của họ. NIKKOR Z 135mm f/1.8 S Plena là ống kính chân dung cao cấp nhất mà Nikon từng sản xuất cho ngàm Z.</p>\r\n<h2>Thiết kế và cấu trúc quang học</h2>\r\n<p>Plena sử dụng 16 thấu kính trong 12 nhóm, bao gồm 1 thấu kính ED, 1 thấu kính SIC (Short-wavelength Invisible Control) và nhiều thấu kính xử lý sắc sai đặc biệt. Cơ chế điều khiển bokeh đặc biệt cho phép Nikon tạo ra những vòng sáng hoàn toàn tròn và đồng đều ở mọi vị trí trong khung hình.</p>\r\n<h2>Bokeh — Tuyệt tác của Plena</h2>\r\n<p>Điều làm Plena đặc biệt là hệ thống lưỡi điều quang 15 lá — nhiều hơn đáng kể so với hầu hết các đối thủ. Kết quả là bokeh cực kỳ tròn và mịn, ngay cả ở các góc của khung hình — điều mà nhiều ống kính khác gặp khó khăn.</p>\r\n<blockquote>Khi nhìn vào những bức ảnh chụp bằng Plena, điều đầu tiên đập vào mắt là sự chuyển tiếp hoàn hảo giữa vùng sắc nét và vùng bokeh. Không có đường cứng, không có halo không mong muốn.</blockquote>\r\n<h2>Hiệu suất thực tế</h2>\r\n<p>Ở f/1.8, Plena cho độ nét cực kỳ ấn tượng, sắc bén đến từng sợi lông mày trong ảnh chân dung. Hệ thống lấy nét nhanh và chính xác, tracking mặt và mắt hoạt động hoàn hảo khi kết hợp với Nikon Z8 hoặc Z9.</p>\r\n<h2>Mức giá và kết luận</h2>\r\n<p>Với mức giá khoảng 68 triệu đồng, Plena không dành cho tất cả mọi người. Nhưng nếu bạn là nhiếp ảnh gia chân dung chuyên nghiệp sử dụng hệ thống Nikon Z và muốn ống kính tốt nhất, Plena chính là câu trả lời hoàn hảo.</p>','/storage/news/bMWRky3UB5L1EK7StNmNRRdDOJ2QP8gQuiwH6BJa.webp','review','Review','Minh Châu',6,0,0,'2026-09-23 23:28:40','2026-09-23 23:38:22'),(9,'Cách chọn ống kính phù hợp với thể loại nhiếp ảnh của bạn','Mỗi thể loại nhiếp ảnh yêu cầu một loại ống kính khác nhau. Hướng dẫn chọn lựa đúng đắn để không phí tiền đầu tư.','<h2>Không có ống kính nào \"tốt nhất\" cho tất cả</h2>\n<p>Một trong những câu hỏi phổ biến nhất từ người mới chơi ảnh là: \"Nên mua ống kính nào?\". Và câu trả lời luôn là: \"Tùy thuộc vào bạn chụp thể loại gì\". Mỗi thể loại nhiếp ảnh có những yêu cầu khác nhau về tiêu cự, khẩu độ và tốc độ lấy nét.</p>\n<h2>Ảnh chân dung (Portrait)</h2>\n<p>Dải tiêu cự lý tưởng: 85mm, 105mm hoặc 135mm. Những tiêu cự này giúp nén phối cảnh một cách flattering cho khuôn mặt và tạo ra khoảng cách vừa phải giữa nhiếp ảnh gia và chủ thể. Khẩu độ tối đa từ f/1.4 đến f/1.8 để tạo bokeh đẹp.</p>\n<p><strong>Gợi ý:</strong> Sony FE 85mm f/1.8, Nikon Z 85mm f/1.8 S, Canon RF 85mm f/1.2L</p>\n<h2>Ảnh đường phố (Street Photography)</h2>\n<p>Tiêu cự 35mm và 50mm là \"ngôn ngữ\" của nhiếp ảnh đường phố. Chúng tái tạo góc nhìn gần với mắt người, giúp ảnh trông tự nhiên. Ống kính nhỏ gọn, ít gây chú ý là lợi thế lớn.</p>\n<p><strong>Gợi ý:</strong> Fujifilm XF 35mm f/2, Ricoh GR IIIx, Sony FE 40mm f/2.5 G</p>\n<h2>Ảnh phong cảnh (Landscape)</h2>\n<p>Góc siêu rộng từ 14mm đến 24mm giúp bạn ôm trọn những cảnh quan rộng lớn. Khẩu độ không cần quá lớn, f/2.8 đến f/4 là đủ vì bạn thường muốn toàn cảnh sắc nét.</p>\n<p><strong>Gợi ý:</strong> Laowa 14mm f/4 FF RL, Sony FE 16-35mm f/2.8 GM</p>\n<h2>Ảnh thể thao / Động vật hoang dã</h2>\n<p>Tiêu cự dài từ 300mm đến 600mm, tốc độ lấy nét nhanh và hệ thống chống rung là những yếu tố quan trọng. Khẩu độ tối đa f/4 cho phép chụp trong điều kiện ánh sáng kém.</p>\n<p><strong>Gợi ý:</strong> Canon RF 600mm f/4L, Nikon Z 400mm f/4.5 S</p>\n<h2>Kết luận</h2>\n<p>Hãy xác định rõ thể loại nhiếp ảnh bạn theo đuổi trước khi đầu tư vào ống kính. Một ống kính phù hợp thể loại sẽ giúp bạn phát huy tối đa sáng tạo và không lãng phí tiền bạc.</p>','https://images.unsplash.com/photo-1526170375885-4d8ecf77b99f?w=1200&auto=format&fit=crop&q=80','tips','Mẹo','An Khoa',11,0,0,'2026-09-23 23:28:40','2026-09-23 23:28:40'),(10,'Tamron 150-500mm f/5-6.7 Di III VC VXD — Tele Zoom đỉnh cao cho Sony E','Ống kính tele zoom cực dài nhưng giá bình dân này có thực sự đáng mua cho những ai yêu thích chụp động vật hoang dã và thể thao?','<h2>Tamron đã làm nên điều không tưởng</h2>\r\n<p>Khi Tamron công bố ống kính 150-500mm cho ngàm Sony E với mức giá dưới 28 triệu đồng, cộng đồng nhiếp ảnh khá hoài nghi. Liệu một ống kính zoom cực dài với giá như vậy có thể cạnh tranh với các ông lớn như Sony hay Nikon không?</p>\r\n<h2>Thiết kế và xây dựng</h2>\r\n<p>Tamron 150-500mm có trọng lượng 1.725g và chiều dài khoảng 210mm ở vị trí 150mm. Ống kính mang chất lượng xây dựng tốt, có gioăng chống bụi và ẩm ở nhiều điểm quan trọng. Vòng zoom êm ái, vòng focus có thể điều chỉnh tốt.</p>\r\n<h2>Hệ thống chống rung VC</h2>\r\n<p>Hệ thống chống rung VC (Vibration Compensation) của Tamron hoạt động tốt hơn mong đợi. Khi kết hợp với chống rung trong thân máy Sony (IBIS), ảnh có thể chụp sắc nét ở tốc độ màn trập chậm đáng ngạc nhiên — khoảng 1/60s ở 500mm trong điều kiện lý tưởng.</p>\r\n<blockquote>Trong một buổi chụp ảnh chim ở rừng quốc gia, Tamron 150-500mm cho phép tôi bắt được những khoảnh khắc rất đẹp mà trước đây tôi phải dùng ống kính đắt gấp 3-4 lần.</blockquote>\r\n<h2>Chất lượng ảnh</h2>\r\n<p>Ở 150-300mm, ống kính cho chất lượng ảnh xuất sắc với độ nét tốt ngay từ khẩu độ tối đa. Ở 400-500mm, chất lượng giảm nhẹ nhưng vẫn hoàn toàn chấp nhận được cho in ấn lớn và sử dụng chuyên nghiệp.</p>\r\n<h2>So sánh với đối thủ</h2>\r\n<p>So với Sony FE 200-600mm f/5.6-6.3 G OSS (giá khoảng 38 triệu), Tamron 150-500mm rẻ hơn đáng kể nhưng chất lượng ảnh thấp hơn một chút. Nếu ngân sách hạn chế, Tamron là lựa chọn xuất sắc.</p>\r\n<h2>Kết luận</h2>\r\n<p>Tamron 150-500mm là ống kính tele zoom tốt nhất trong tầm giá của nó cho Sony E-mount. Nếu bạn muốn chụp thể thao, động vật hoang dã hoặc chim muông với ngân sách hợp lý, đây là lựa chọn không thể bỏ qua.</p>','/storage/news/q5FOaDmnYHvn9Yx0tWbEzfjWN17v6rbfgTPmWR3g.jpg','review','Review','Hồng Đức',13,0,0,'2026-09-23 23:28:40','2026-09-23 23:40:24'),(11,'Hiểu về khẩu độ, tốc độ màn trập và ISO — Bộ ba vàng của nhiếp ảnh','Tam giác phơi sáng là kiến thức nền tảng quan trọng nhất mà mọi nhiếp ảnh gia cần nắm vững. Hướng dẫn toàn diện từ A đến Z.','<h2>Tam giác phơi sáng là gì?</h2>\n<p>Tam giác phơi sáng (Exposure Triangle) là mối quan hệ tương tác giữa ba yếu tố: Khẩu độ (Aperture), Tốc độ màn trập (Shutter Speed) và ISO. Ba yếu tố này cùng nhau quyết định mức độ sáng tối (exposure) của bức ảnh. Hiểu cách chúng hoạt động là bước đầu tiên để làm chủ việc chụp ở chế độ thủ công (Manual).</p>\n<h2>Khẩu độ (Aperture) — Kiểm soát ánh sáng và chiều sâu trường ảnh</h2>\n<p>Khẩu độ là kích thước của lỗ mở trong ống kính, ký hiệu bằng f-stop (f/1.4, f/2.8, f/5.6...). Số f càng nhỏ, lỗ mở càng lớn, càng nhiều ánh sáng vào, và chiều sâu trường ảnh (DOF) càng mỏng — tức là nền ảnh sẽ mờ nhiều hơn (bokeh).</p>\n<p><strong>Ứng dụng:</strong> Chụp chân dung dùng f/1.4 - f/2.8 để bokeh đẹp. Chụp phong cảnh dùng f/8 - f/11 để toàn ảnh sắc nét.</p>\n<h2>Tốc độ màn trập (Shutter Speed) — Đóng băng hoặc tạo chuyển động</h2>\n<p>Tốc độ màn trập là thời gian cảm biến tiếp xúc với ánh sáng, tính bằng giây (1/2000s, 1/250s, 1s...). Tốc độ nhanh đóng băng chuyển động; tốc độ chậm tạo hiệu ứng mờ chuyển động (motion blur) đẹp mắt.</p>\n<p><strong>Quy tắc vàng:</strong> Tốc độ màn trập tối thiểu = 1 / tiêu cự ống kính. Ví dụ: 50mm → tốc độ tối thiểu 1/50s để tránh ảnh bị rung.</p>\n<h2>ISO — Độ nhạy sáng</h2>\n<p>ISO là độ nhạy sáng của cảm biến. ISO thấp (100-400) cho ảnh ít nhiễu, sạch đẹp. ISO cao (1600+) cho phép chụp trong ánh sáng kém nhưng ảnh sẽ có nhiễu hạt (noise) nhiều hơn.</p>\n<blockquote>Quy tắc đơn giản: Luôn dùng ISO thấp nhất có thể. Chỉ tăng ISO khi bạn không thể điều chỉnh khẩu độ hay tốc độ màn trập thêm nữa.</blockquote>\n<h2>Cách cân bằng ba yếu tố</h2>\n<p>Mục tiêu là đạt được exposure đúng (không quá sáng, không quá tối) trong khi đạt được hiệu ứng hình ảnh mong muốn. Ví dụ: Muốn chụp thác nước mờ (slow shutter) → dùng tốc độ chậm → cần khẩu độ nhỏ hơn và/hoặc ISO thấp hơn để bù lại lượng ánh sáng dư.</p>\n<h2>Thực hành là chìa khóa</h2>\n<p>Lý thuyết chỉ là nền tảng. Hãy ra ngoài và thực hành bằng cách thử nghiệm các kết hợp khác nhau. Sau một thời gian, việc điều chỉnh ba yếu tố này sẽ trở thành bản năng tự nhiên.</p>','https://images.unsplash.com/photo-1607462109225-6b64ae2dd3cb?w=1200&auto=format&fit=crop&q=80','tips','Mẹo','Đăng Khoa',9,0,0,'2026-09-23 23:28:40','2026-09-23 23:28:40'),(12,'Fujifilm X100VI — Máy ảnh compact hoàn hảo cho người yêu phong cách retro','Fujifilm X100VI là phiên bản nâng cấp toàn diện của dòng X100 huyền thoại, tích hợp cảm biến 40MP và chống rung IBIS lần đầu tiên trong dòng này.','<h2>X100VI — Sự kết hợp hoàn hảo giữa cổ điển và hiện đại</h2>\n<p>Fujifilm X100VI chính thức ra mắt đầu năm 2026 và ngay lập tức gây ra cơn sốt trên toàn thế giới. Máy cháy hàng liên tục trong nhiều tháng — một hiện tượng hiếm gặp trong thị trường máy ảnh hiện nay.</p>\n<h2>Thiết kế — Vẻ đẹp trường tồn</h2>\n<p>X100VI giữ nguyên ngôn ngữ thiết kế đặc trưng của dòng X100 từ năm 2011 — vẻ ngoài rangefinder retro với các núm điều chỉnh cơ học, thân hợp kim nhôm chắc chắn và cảm giác cầm nắm tuyệt vời. Ống kính 23mm f/2 cố định (tương đương 35mm full-frame) tích hợp trong thân máy nhỏ gọn.</p>\n<h2>Cảm biến 40MP mới</h2>\n<p>Đây là nâng cấp lớn nhất của X100VI — cảm biến X-Trans CMOS 5 HR 40MP mới nhất của Fujifilm. Chất lượng ảnh ở ISO thấp đạt mức xuất sắc, với dynamic range rộng và khả năng giữ chi tiết trong cả vùng sáng lẫn vùng tối ấn tượng.</p>\n<blockquote>Chụp đường phố với X100VI là một trải nghiệm khó quên. Máy nhỏ gọn, không gây chú ý, và film simulation của Fujifilm tạo ra những tông màu đẹp đến mức nhiều ảnh gần như không cần hậu kỳ.</blockquote>\n<h2>IBIS — Sự khác biệt lớn</h2>\n<p>Lần đầu tiên trong lịch sử dòng X100, Fujifilm tích hợp hệ thống chống rung 5 trục (IBIS) với hiệu quả lên đến 6 stops. Đây là thay đổi cách mạng, cho phép chụp handheld ở tốc độ màn trập cực chậm và quay video ổn định hơn nhiều.</p>\n<h2>Kết luận</h2>\n<p>Fujifilm X100VI là máy ảnh hoàn hảo cho những ai muốn một chiếc compact chất lượng cao để mang theo hàng ngày. Mức giá khoảng 45 triệu đồng có vẻ cao cho một máy compact, nhưng chất lượng và trải nghiệm sử dụng hoàn toàn xứng đáng.</p>','https://images.unsplash.com/photo-1516035069371-29a1b244cc32?w=1200&auto=format&fit=crop&q=80','review','Review','Thu Hằng',7,0,0,'2026-09-23 23:28:40','2026-09-23 23:28:40'),(13,'10 lỗi phổ biến người mới chụp ảnh thường mắc và cách khắc phục','Từ chụp ảnh bị rung đến bố cục nghèo nàn, những lỗi này ai cũng từng mắc. Học cách nhận biết và sửa chữa chúng ngay hôm nay.','<h2>Học từ sai lầm — Con đường nhanh nhất để tiến bộ</h2>\r\n<p>Mọi nhiếp ảnh gia chuyên nghiệp đều đã từng là người mới bắt đầu và mắc những lỗi cơ bản. Điều quan trọng là nhận biết những lỗi đó và sửa chữa chúng sớm để không hình thành thói quen xấu.</p>\r\n<h2>1. Ảnh bị rung (Camera Shake)</h2>\r\n<p><strong>Nguyên nhân:</strong> Tốc độ màn trập quá chậm so với tiêu cự ống kính đang dùng.<br>\r\n<strong>Khắc phục:</strong> Áp dụng quy tắc: tốc độ tối thiểu = 1/tiêu cự. Dùng 85mm thì tốc độ tối thiểu là 1/85s. Tốt hơn hãy dùng 1/125s.</p>\r\n<h2>2. Chụp ở Auto hoàn toàn</h2>\r\n<p><strong>Nguyên nhân:</strong> Ngại học chế độ thủ công, sợ hỏng ảnh.<br>\r\n<strong>Khắc phục:</strong> Bắt đầu với Aperture Priority (Av/A), chỉ kiểm soát khẩu độ. Đây là chế độ bán tự động an toàn nhất để học cách kiểm soát độ sâu trường ảnh.</p>\r\n<h2>3. Không kiểm tra histogram</h2>\r\n<p><strong>Nguyên nhân:</strong> Dựa vào màn hình LCD để đánh giá exposure, nhưng LCD có thể không chính xác.<br>\r\n<strong>Khắc phục:</strong> Bật hiển thị histogram. Histogram là biểu đồ chính xác nhất để đánh giá exposure.</p>\r\n<h2>4. Bố cục nhàm chán</h2>\r\n<p><strong>Nguyên nhân:</strong> Luôn đặt chủ thể vào trung tâm.<br>\r\n<strong>Khắc phục:</strong> Áp dụng quy tắc 1/3. Di chuyển xung quanh để tìm góc độ thú vị hơn trước khi bấm máy.</p>\r\n<h2>5. Chụp ở định dạng JPEG khi mới bắt đầu học hậu kỳ</h2>\r\n<p><strong>Nguyên nhân:</strong> Không biết về RAW.<br>\r\n<strong>Khắc phục:</strong> Chụp RAW + JPEG. RAW lưu giữ đầy đủ thông tin ảnh, cho phép chỉnh sửa nhiều hơn trong Lightroom hoặc Capture One.</p>\r\n<blockquote>Một bức ảnh RAW có thể được \"cứu\" khi exposure sai ±2 stops. Với JPEG, bạn chỉ có một cơ hội duy nhất.</blockquote>\r\n<h2>6. Không chú ý đến ánh sáng</h2>\r\n<p><strong>Nguyên nhân:</strong> Chỉ tập trung vào chủ thể, quên mất ánh sáng.<br>\r\n<strong>Khắc phục:</strong> Quan sát ánh sáng trước khi cầm máy lên. \"Golden hour\" (1 tiếng sau mặt trời mọc và trước khi lặn) luôn cho ánh sáng đẹp nhất.</p>\r\n<h2>7. ISO quá cao không cần thiết</h2>\r\n<p><strong>Nguyên nhân:</strong> Quên reset ISO về mức thấp sau khi chụp trong nhà.<br>\r\n<strong>Khắc phục:</strong> Tạo thói quen kiểm tra ISO mỗi khi thay đổi môi trường chụp. Hoặc dùng Auto ISO với giới hạn tối đa.</p>\r\n<h2>Kết luận</h2>\r\n<p>Đừng nản lòng khi mắc sai lầm. Mỗi lỗi là một bài học quý giá. Hãy review lại ảnh của mình thường xuyên, xác định vấn đề và tập trung cải thiện từng điểm một. Tiến bộ sẽ đến nhanh hơn bạn nghĩ.</p>','/storage/news/SDNBMXchM44HsKGZFhngswidWdCTKZFzn6B64uT0.png','tips','Mẹo','Việt Hưng',10,0,0,'2026-09-23 23:28:40','2026-09-23 23:42:30');
/*!40000 ALTER TABLE `news` ENABLE KEYS */;
