INSERT INTO `products` VALUES (1,1,'Sony FE 24-70mm f/2.8 GM II','SEL2470GM2','24-70mm','f/2.8','Sony E-Mount',49990000.00,1,'https://m.media-amazon.com/images/I/81x+T2De7aL.jpg','<h3><strong>1. Tổng quan về Sony FE 24-70mm f/2.8 GM II</strong></h3>\n<p>Ống kính <strong>Sony FE 24-70mm f/2.8 GM II</strong> là một kiệt tác thực sự đến từ thương hiệu máy ảnh và ống kính hàng đầu thế giới Sony. Được chế tác với độ hoàn thiện không thể chê vào đâu được, sản phẩm này ra đời để làm hài lòng cả những nhiếp ảnh gia và nhà quay phim chuyên nghiệp khó tính nhất. Nó mang trong mình những công nghệ quang học tiên tiến nhất ở thời điểm hiện tại, đem đến một sức mạnh vượt trội giúp bạn ghi lại mọi khoảnh khắc với độ chính xác và chất lượng hình ảnh đáng kinh ngạc.</p>\n<h3><strong>2. Cấu trúc quang học và Độ sắc nét</strong></h3>\n<p>Trái tim của <strong>Sony FE 24-70mm f/2.8 GM II</strong> nằm ở hệ thống quang học vô cùng tinh vi. Với sự kết hợp của các thấu kính phi cầu đặc biệt (Aspherical) và các thấu kính tán xạ thấp (ED/Super ED), ống kính này triệt tiêu gần như hoàn toàn hiện tượng quang sai màu, viền tím và méo hình. Dù bạn chụp ở trung tâm hay sát rìa bức ảnh, độ phân giải vẫn được duy trì ở mức tối đa.</p>\n<p>Thêm vào đó, lớp phủ độc quyền của Sony giúp ngăn chặn triệt để hiện tượng bóng ma (ghosting) và lóa sáng (flare), ngay cả khi bạn phải đối mặt trực tiếp với nguồn sáng mạnh. Điều này mang lại độ tương phản tuyệt vời và màu sắc sống động, chân thực đến từng chi tiết nhỏ nhất.</p>\n<h3><strong>3. Hiệu năng Lấy nét tự động (AF) siêu tốc</strong></h3>\n<p>Được trang bị hệ thống motor lấy nét tuyến tính thế hệ mới nhất, ống kính phản hồi cực kỳ nhanh chóng và êm ái. Hệ thống AF không chỉ lấy nét chớp nhoáng mà còn theo dõi chủ thể cực kỳ chính xác. Dù bạn đang chụp ảnh thể thao với tốc độ chuyển động chóng mặt, hay quay những thước phim điện ảnh yêu cầu độ mượt mà tuyệt đối, <strong>Sony FE 24-70mm f/2.8 GM II</strong> đều đáp ứng một cách xuất sắc mà không gây ra bất kỳ tiếng ồn cơ học nào.</p>\n<h3><strong>4. Thiết kế công thái học và Độ bền bỉ</strong></h3>\n<p>Bất chấp việc sở hữu sức mạnh quang học khủng, ống kính lại có một thiết kế vô cùng cân đối và vừa vặn khi gắn lên thân máy. Vỏ ngoài được chế tạo từ hợp kim cao cấp không chỉ giúp giảm tối đa trọng lượng mà còn mang lại cảm giác cầm nắm đầm tay, chắc chắn.</p>\n<p>Đặc biệt, hệ thống ron cao su bảo vệ được bố trí tỉ mỉ ở mọi khớp nối và nút bấm, giúp ống kính có khả năng chống bụi và chống nước văng cực tốt. Lớp phủ Fluorine ở thấu kính phía trước còn giúp bạn dễ dàng lau chùi nước, dầu mỡ hay dấu vân tay, bảo vệ ống kính an toàn trong những môi trường làm việc khắc nghiệt nhất.</p>\n<h3><strong>5. Khả năng sáng tạo không giới hạn</strong></h3>\n<p>Với thông số tiêu cự 24-70mm và khẩu độ lớn f/2.8, bạn nắm trong tay khả năng kiểm soát độ sâu trường ảnh tuyệt đối. Hãy tưởng tượng những bức ảnh chân dung với chủ thể sắc nét đến từng sợi tóc, nổi bật hoàn toàn trên một phông nền được làm mờ (bokeh) mềm mại như nhung. Hoặc khả năng bắt sáng tuyệt vời giúp bạn tự tin chụp ảnh trong điều kiện ánh sáng cực yếu mà không cần tăng ISO lên mức nhiễu hạt.</p>\n<p>Từ chụp ảnh phong cảnh bao la, kiến trúc hùng vĩ, nhiếp ảnh đường phố đời thường cho đến những sự kiện lộng lẫy, <strong>Sony FE 24-70mm f/2.8 GM II</strong> không chỉ là một công cụ, mà là người bạn đồng hành truyền cảm hứng bất tận để bạn vượt qua mọi giới hạn của sự sáng tạo.</p>\n','Sony',NULL,'[{\"url\":\"https:\\/\\/media.vietravel.com\\/images\\/Content\\/du-lich-bac-cuc-4.png\",\"cap\":\"Th\\u1ea5u k\\u00ednh tr\\u01b0\\u1edbc\"},{\"url\":\"https:\\/\\/bocapvang.net\\/wp-content\\/uploads\\/2022\\/07\\/phong-canh-dep-o-viet-nam-8.jpg.crdownload.jpg\",\"cap\":\"G\\u00f3c 45 \\u0111\\u1ed9\"},{\"url\":\"https:\\/\\/m.yodycdn.com\\/blog\\/phong-canh-dep-o-viet-nam-yody-vn-13.jpg\",\"cap\":\"M\\u1eb7t b\\u00ean tr\\u00e1i\"},{\"url\":\"https:\\/\\/scr.vn\\/wp-content\\/uploads\\/2020\\/08\\/H%C3%ACnh-c%E1%BA%A3nh-ho%C3%A0ng-h%C3%B4n-%C4%91%E1%BA%B9p-4k-scaled.jpg\",\"cap\":\"G\\u00f3c t\\u1eeb tr\\u00ean xu\\u1ed1ng\"},{\"url\":\"https:\\/\\/vphoto.vietnam.vn\\/thumb\\/1200x675\\/vietnam\\/resource\\/IMAGE\\/2026\\/09\\/17\\/1789619523936_anh-man-hinh-2026-09-17-luc-11-31-09.png\",\"cap\":\"Chi ti\\u1ebft ng\\u00e0m\"},{\"url\":\"https:\\/\\/datviettour.com.vn\\/uploads\\/images\\/tin-tuc-SEO-chau-au\\/tong-hop\\/danh-thang\\/bac-cuc-quang-day-mau-sac.jpg\",\"cap\":\"G\\u00f3c nh\\u00ecn ch\\u00ednh di\\u1ec7n\"}]','[{\"url\":\"https:\\/\\/png.pngtree.com\\/background\\/20230403\\/original\\/pngtree-aurora-borealis-on-night-sky-over-winter-landscape-with-snow-aurora-picture-image_2294003.jpg\",\"tag\":\"Phong c\\u1ea3nh h\\u00f9ng v\\u0129\",\"text\":\"Kho\\u1ea3nh kh\\u1eafc kh\\u00f3 qu\\u00ean\"},{\"url\":\"https:\\/\\/imgt.taimienphi.vn\\/cf\\/Images\\/dip\\/2023\\/10\\/13\\/anh-hoang-hon-6.jpg\",\"tag\":\"\\u0110\\u1ed9ng v\\u1eadt hoang d\\u00e3\",\"text\":\"\\u00c1nh s\\u00e1ng v\\u00e0 b\\u00f3ng t\\u1ed1i h\\u00f2a quy\\u1ec7n\"},{\"url\":\"https:\\/\\/th.bing.com\\/th\\/id\\/R.3549f07ff08d2a84ef6ad5eb6f24e6af?rik=m%2f9HNszy6tMXhA&pid=ImgRaw&r=0\",\"tag\":\"Th\\u00e0nh ph\\u1ed1\",\"text\":\"B\\u1ee9c \\u1ea3nh mang \\u0111\\u1ea7y c\\u1ea3m x\\u00fac\"},{\"url\":\"https:\\/\\/media.istockphoto.com\\/id\\/481203650\\/vi\\/anh\\/nh%C3%A0n-b%E1%BA%AFc-c%E1%BB%B1c.jpg?s=170667a&w=0&k=20&c=sChEnYEAYj673fUhthWMfgeRiEwdoUHkBKZxiGKtqFI=\",\"tag\":\"Ch\\u00e2n dung ngh\\u1ec7 thu\\u1eadt\",\"text\":\"Ch\\u1ee5p c\\u1eadn c\\u1ea3nh chi ti\\u1ebft\"},{\"url\":\"https:\\/\\/www.migolatravel.com\\/wp-content\\/uploads\\/2019\\/05\\/bac-cuc-3-1.jpg\",\"tag\":\"Street Photography\",\"text\":\"S\\u1eafc m\\u00e0u tuy\\u1ec7t \\u0111\\u1eb9p trong \\u0111\\u00eam\"}]','in_stock','2026-08-15 00:33:07','2026-09-29 10:20:44'),(2,2,'Sony FE 50mm f/1.2 GM','SEL50F12GM','50mm','f/1.2','Sony E-Mount',47990000.00,8,'https://www.bhphotovideo.com/images/fb/sony_sel50f12gm_fe_50mm_f_1_2_gm_1630079.jpg','<h3><strong>1. Tổng quan về Sony FE 50mm f/1.2 GM</strong></h3>\n<p>Ống kính <strong>Sony FE 50mm f/1.2 GM</strong> là một kiệt tác thực sự đến từ thương hiệu máy ảnh và ống kính hàng đầu thế giới Sony. Được chế tác với độ hoàn thiện không thể chê vào đâu được, sản phẩm này ra đời để làm hài lòng cả những nhiếp ảnh gia và nhà quay phim chuyên nghiệp khó tính nhất. Nó mang trong mình những công nghệ quang học tiên tiến nhất ở thời điểm hiện tại, đem đến một sức mạnh vượt trội giúp bạn ghi lại mọi khoảnh khắc với độ chính xác và chất lượng hình ảnh đáng kinh ngạc.</p>\n<h3><strong>2. Cấu trúc quang học và Độ sắc nét</strong></h3>\n<p>Trái tim của <strong>Sony FE 50mm f/1.2 GM</strong> nằm ở hệ thống quang học vô cùng tinh vi. Với sự kết hợp của các thấu kính phi cầu đặc biệt (Aspherical) và các thấu kính tán xạ thấp (ED/Super ED), ống kính này triệt tiêu gần như hoàn toàn hiện tượng quang sai màu, viền tím và méo hình. Dù bạn chụp ở trung tâm hay sát rìa bức ảnh, độ phân giải vẫn được duy trì ở mức tối đa.</p>\n<p>Thêm vào đó, lớp phủ độc quyền của Sony giúp ngăn chặn triệt để hiện tượng bóng ma (ghosting) và lóa sáng (flare), ngay cả khi bạn phải đối mặt trực tiếp với nguồn sáng mạnh. Điều này mang lại độ tương phản tuyệt vời và màu sắc sống động, chân thực đến từng chi tiết nhỏ nhất.</p>\n<h3><strong>3. Hiệu năng Lấy nét tự động (AF) siêu tốc</strong></h3>\n<p>Được trang bị hệ thống motor lấy nét tuyến tính thế hệ mới nhất, ống kính phản hồi cực kỳ nhanh chóng và êm ái. Hệ thống AF không chỉ lấy nét chớp nhoáng mà còn theo dõi chủ thể cực kỳ chính xác. Dù bạn đang chụp ảnh thể thao với tốc độ chuyển động chóng mặt, hay quay những thước phim điện ảnh yêu cầu độ mượt mà tuyệt đối, <strong>Sony FE 50mm f/1.2 GM</strong> đều đáp ứng một cách xuất sắc mà không gây ra bất kỳ tiếng ồn cơ học nào.</p>\n<h3><strong>4. Thiết kế công thái học và Độ bền bỉ</strong></h3>\n<p>Bất chấp việc sở hữu sức mạnh quang học khủng, ống kính lại có một thiết kế vô cùng cân đối và vừa vặn khi gắn lên thân máy. Vỏ ngoài được chế tạo từ hợp kim cao cấp không chỉ giúp giảm tối đa trọng lượng mà còn mang lại cảm giác cầm nắm đầm tay, chắc chắn.</p>\n<p>Đặc biệt, hệ thống ron cao su bảo vệ được bố trí tỉ mỉ ở mọi khớp nối và nút bấm, giúp ống kính có khả năng chống bụi và chống nước văng cực tốt. Lớp phủ Fluorine ở thấu kính phía trước còn giúp bạn dễ dàng lau chùi nước, dầu mỡ hay dấu vân tay, bảo vệ ống kính an toàn trong những môi trường làm việc khắc nghiệt nhất.</p>\n<h3><strong>5. Khả năng sáng tạo không giới hạn</strong></h3>\n<p>Với thông số tiêu cự 50mm và khẩu độ lớn f/1.2, bạn nắm trong tay khả năng kiểm soát độ sâu trường ảnh tuyệt đối. Hãy tưởng tượng những bức ảnh chân dung với chủ thể sắc nét đến từng sợi tóc, nổi bật hoàn toàn trên một phông nền được làm mờ (bokeh) mềm mại như nhung. Hoặc khả năng bắt sáng tuyệt vời giúp bạn tự tin chụp ảnh trong điều kiện ánh sáng cực yếu mà không cần tăng ISO lên mức nhiễu hạt.</p>\n<p>Từ chụp ảnh phong cảnh bao la, kiến trúc hùng vĩ, nhiếp ảnh đường phố đời thường cho đến những sự kiện lộng lẫy, <strong>Sony FE 50mm f/1.2 GM</strong> không chỉ là một công cụ, mà là người bạn đồng hành truyền cảm hứng bất tận để bạn vượt qua mọi giới hạn của sự sáng tạo.</p>\n','Sony',NULL,'[{\"url\":\"https:\\/\\/m.yodycdn.com\\/blog\\/phong-canh-dep-o-viet-nam-yody-vn-13.jpg\",\"cap\":\"G\\u00f3c t\\u1eeb tr\\u00ean xu\\u1ed1ng\"},{\"url\":\"https:\\/\\/scr.vn\\/wp-content\\/uploads\\/2020\\/08\\/H%C3%ACnh-c%E1%BA%A3nh-ho%C3%A0ng-h%C3%B4n-%C4%91%E1%BA%B9p-4k-scaled.jpg\",\"cap\":\"Th\\u1ea5u k\\u00ednh tr\\u01b0\\u1edbc\"},{\"url\":\"https:\\/\\/media.vietravel.com\\/images\\/Content\\/du-lich-bac-cuc-4.png\",\"cap\":\"G\\u00f3c nh\\u00ecn ch\\u00ednh di\\u1ec7n\"},{\"url\":\"https:\\/\\/mia.vn\\/media\\/uploads\\/blog-du-lich\\/canh-dep-nuoc-my-12-1718757524.jpg\",\"cap\":\"M\\u1eb7t b\\u00ean tr\\u00e1i\"},{\"url\":\"https:\\/\\/bocapvang.net\\/wp-content\\/uploads\\/2022\\/07\\/phong-canh-dep-o-viet-nam-8.jpg.crdownload.jpg\",\"cap\":\"Chi ti\\u1ebft ng\\u00e0m\"},{\"url\":\"https:\\/\\/png.pngtree.com\\/background\\/20230403\\/original\\/pngtree-aurora-borealis-on-night-sky-over-winter-landscape-with-snow-aurora-picture-image_2294003.jpg\",\"cap\":\"G\\u00f3c 45 \\u0111\\u1ed9\"}]','[{\"url\":\"https:\\/\\/datviettour.com.vn\\/uploads\\/images\\/tin-tuc-SEO-chau-au\\/tong-hop\\/danh-thang\\/bac-cuc-quang-day-mau-sac.jpg\",\"tag\":\"C\\u1ef1c quang\",\"text\":\"Kho\\u1ea3nh kh\\u1eafc kh\\u00f3 qu\\u00ean\"},{\"url\":\"https:\\/\\/imgt.taimienphi.vn\\/cf\\/Images\\/dip\\/2023\\/10\\/13\\/anh-hoang-hon-6.jpg\",\"tag\":\"\\u0110\\u1ed9ng v\\u1eadt hoang d\\u00e3\",\"text\":\"Ch\\u1ee5p c\\u1eadn c\\u1ea3nh chi ti\\u1ebft\"},{\"url\":\"https:\\/\\/vphoto.vietnam.vn\\/thumb\\/1200x675\\/vietnam\\/resource\\/IMAGE\\/2026\\/09\\/17\\/1789619523936_anh-man-hinh-2026-09-17-luc-11-31-09.png\",\"tag\":\"Ch\\u00e2n dung ngh\\u1ec7 thu\\u1eadt\",\"text\":\"S\\u1eafc m\\u00e0u tuy\\u1ec7t \\u0111\\u1eb9p trong \\u0111\\u00eam\"},{\"url\":\"https:\\/\\/th.bing.com\\/th\\/id\\/R.3549f07ff08d2a84ef6ad5eb6f24e6af?rik=m%2f9HNszy6tMXhA&pid=ImgRaw&r=0\",\"tag\":\"Phong c\\u1ea3nh h\\u00f9ng v\\u0129\",\"text\":\"G\\u00f3c ph\\u1ed1 nh\\u1ed9n nh\\u1ecbp\"},{\"url\":\"https:\\/\\/www.migolatravel.com\\/wp-content\\/uploads\\/2019\\/05\\/bac-cuc-3-1.jpg\",\"tag\":\"Th\\u00e0nh ph\\u1ed1\",\"text\":\"B\\u1ee9c \\u1ea3nh mang \\u0111\\u1ea7y c\\u1ea3m x\\u00fac\"}]','in_stock','2026-08-15 00:33:07','2026-09-29 10:20:44'),(3,4,'Sony FE 70-200mm f/2.8 GM OSS II','SEL70200GM2','70-200mm','f/2.8','Sony E-Mount',62990000.00,6,'https://gayatekno.id/wp-content/uploads/2021/10/Foto-1-Tampilan-Sony-FE-70-200mm-F2.8-GM-OSS-II.png','<h3><strong>1. Tổng quan về Sony FE 70-200mm f/2.8 GM OSS II</strong></h3>\n<p>Ống kính <strong>Sony FE 70-200mm f/2.8 GM OSS II</strong> là một kiệt tác thực sự đến từ thương hiệu máy ảnh và ống kính hàng đầu thế giới Sony. Được chế tác với độ hoàn thiện không thể chê vào đâu được, sản phẩm này ra đời để làm hài lòng cả những nhiếp ảnh gia và nhà quay phim chuyên nghiệp khó tính nhất. Nó mang trong mình những công nghệ quang học tiên tiến nhất ở thời điểm hiện tại, đem đến một sức mạnh vượt trội giúp bạn ghi lại mọi khoảnh khắc với độ chính xác và chất lượng hình ảnh đáng kinh ngạc.</p>\n<h3><strong>2. Cấu trúc quang học và Độ sắc nét</strong></h3>\n<p>Trái tim của <strong>Sony FE 70-200mm f/2.8 GM OSS II</strong> nằm ở hệ thống quang học vô cùng tinh vi. Với sự kết hợp của các thấu kính phi cầu đặc biệt (Aspherical) và các thấu kính tán xạ thấp (ED/Super ED), ống kính này triệt tiêu gần như hoàn toàn hiện tượng quang sai màu, viền tím và méo hình. Dù bạn chụp ở trung tâm hay sát rìa bức ảnh, độ phân giải vẫn được duy trì ở mức tối đa.</p>\n<p>Thêm vào đó, lớp phủ độc quyền của Sony giúp ngăn chặn triệt để hiện tượng bóng ma (ghosting) và lóa sáng (flare), ngay cả khi bạn phải đối mặt trực tiếp với nguồn sáng mạnh. Điều này mang lại độ tương phản tuyệt vời và màu sắc sống động, chân thực đến từng chi tiết nhỏ nhất.</p>\n<h3><strong>3. Hiệu năng Lấy nét tự động (AF) siêu tốc</strong></h3>\n<p>Được trang bị hệ thống motor lấy nét tuyến tính thế hệ mới nhất, ống kính phản hồi cực kỳ nhanh chóng và êm ái. Hệ thống AF không chỉ lấy nét chớp nhoáng mà còn theo dõi chủ thể cực kỳ chính xác. Dù bạn đang chụp ảnh thể thao với tốc độ chuyển động chóng mặt, hay quay những thước phim điện ảnh yêu cầu độ mượt mà tuyệt đối, <strong>Sony FE 70-200mm f/2.8 GM OSS II</strong> đều đáp ứng một cách xuất sắc mà không gây ra bất kỳ tiếng ồn cơ học nào.</p>\n<h3><strong>4. Thiết kế công thái học và Độ bền bỉ</strong></h3>\n<p>Bất chấp việc sở hữu sức mạnh quang học khủng, ống kính lại có một thiết kế vô cùng cân đối và vừa vặn khi gắn lên thân máy. Vỏ ngoài được chế tạo từ hợp kim cao cấp không chỉ giúp giảm tối đa trọng lượng mà còn mang lại cảm giác cầm nắm đầm tay, chắc chắn.</p>\n<p>Đặc biệt, hệ thống ron cao su bảo vệ được bố trí tỉ mỉ ở mọi khớp nối và nút bấm, giúp ống kính có khả năng chống bụi và chống nước văng cực tốt. Lớp phủ Fluorine ở thấu kính phía trước còn giúp bạn dễ dàng lau chùi nước, dầu mỡ hay dấu vân tay, bảo vệ ống kính an toàn trong những môi trường làm việc khắc nghiệt nhất.</p>\n<h3><strong>5. Khả năng sáng tạo không giới hạn</strong></h3>\n<p>Với thông số tiêu cự 70-200mm và khẩu độ lớn f/2.8, bạn nắm trong tay khả năng kiểm soát độ sâu trường ảnh tuyệt đối. Hãy tưởng tượng những bức ảnh chân dung với chủ thể sắc nét đến từng sợi tóc, nổi bật hoàn toàn trên một phông nền được làm mờ (bokeh) mềm mại như nhung. Hoặc khả năng bắt sáng tuyệt vời giúp bạn tự tin chụp ảnh trong điều kiện ánh sáng cực yếu mà không cần tăng ISO lên mức nhiễu hạt.</p>\n<p>Từ chụp ảnh phong cảnh bao la, kiến trúc hùng vĩ, nhiếp ảnh đường phố đời thường cho đến những sự kiện lộng lẫy, <strong>Sony FE 70-200mm f/2.8 GM OSS II</strong> không chỉ là một công cụ, mà là người bạn đồng hành truyền cảm hứng bất tận để bạn vượt qua mọi giới hạn của sự sáng tạo.</p>\n','Sony',NULL,'[{\"url\":\"https:\\/\\/www.migolatravel.com\\/wp-content\\/uploads\\/2019\\/05\\/bac-cuc-3-1.jpg\",\"cap\":\"Th\\u1ea5u k\\u00ednh tr\\u01b0\\u1edbc\"},{\"url\":\"https:\\/\\/vphoto.vietnam.vn\\/thumb\\/1200x675\\/vietnam\\/resource\\/IMAGE\\/2026\\/09\\/17\\/1789619523936_anh-man-hinh-2026-09-17-luc-11-31-09.png\",\"cap\":\"G\\u00f3c t\\u1eeb tr\\u00ean xu\\u1ed1ng\"},{\"url\":\"https:\\/\\/bocapvang.net\\/wp-content\\/uploads\\/2022\\/07\\/phong-canh-dep-o-viet-nam-8.jpg.crdownload.jpg\",\"cap\":\"G\\u00f3c 45 \\u0111\\u1ed9\"},{\"url\":\"https:\\/\\/mia.vn\\/media\\/uploads\\/blog-du-lich\\/du-lich-bac-cuc-6-1728749566.jpg\",\"cap\":\"M\\u1eb7t b\\u00ean tr\\u00e1i\"},{\"url\":\"https:\\/\\/scr.vn\\/wp-content\\/uploads\\/2020\\/08\\/H%C3%ACnh-c%E1%BA%A3nh-ho%C3%A0ng-h%C3%B4n-%C4%91%E1%BA%B9p-4k-scaled.jpg\",\"cap\":\"Chi ti\\u1ebft ng\\u00e0m\"},{\"url\":\"https:\\/\\/png.pngtree.com\\/background\\/20230403\\/original\\/pngtree-aurora-borealis-on-night-sky-over-winter-landscape-with-snow-aurora-picture-image_2294003.jpg\",\"cap\":\"G\\u00f3c nh\\u00ecn ch\\u00ednh di\\u1ec7n\"}]','[{\"url\":\"https:\\/\\/mia.vn\\/media\\/uploads\\/blog-du-lich\\/canh-dep-nuoc-my-12-1718757524.jpg\",\"tag\":\"Ch\\u00e2n dung ngh\\u1ec7 thu\\u1eadt\",\"text\":\"Ch\\u1ee5p c\\u1eadn c\\u1ea3nh chi ti\\u1ebft\"},{\"url\":\"https:\\/\\/m.yodycdn.com\\/blog\\/phong-canh-dep-o-viet-nam-yody-vn-13.jpg\",\"tag\":\"Th\\u00e0nh ph\\u1ed1\",\"text\":\"B\\u1ee9c \\u1ea3nh mang \\u0111\\u1ea7y c\\u1ea3m x\\u00fac\"},{\"url\":\"https:\\/\\/media.istockphoto.com\\/id\\/481203650\\/vi\\/anh\\/nh%C3%A0n-b%E1%BA%AFc-c%E1%BB%B1c.jpg?s=170667a&w=0&k=20&c=sChEnYEAYj673fUhthWMfgeRiEwdoUHkBKZxiGKtqFI=\",\"tag\":\"\\u0110\\u1ed9ng v\\u1eadt hoang d\\u00e3\",\"text\":\"\\u00c1nh s\\u00e1ng v\\u00e0 b\\u00f3ng t\\u1ed1i h\\u00f2a quy\\u1ec7n\"},{\"url\":\"https:\\/\\/imgt.taimienphi.vn\\/cf\\/Images\\/dip\\/2023\\/10\\/13\\/anh-hoang-hon-6.jpg\",\"tag\":\"C\\u1ef1c quang\",\"text\":\"Kho\\u1ea3nh kh\\u1eafc kh\\u00f3 qu\\u00ean\"},{\"url\":\"https:\\/\\/media.vietravel.com\\/images\\/Content\\/du-lich-bac-cuc-4.png\",\"tag\":\"Street Photography\",\"text\":\"G\\u00f3c ph\\u1ed1 nh\\u1ed9n nh\\u1ecbp\"}]','in_stock','2026-08-15 00:33:07','2026-09-29 10:20:44'),(4,1,'Canon RF 24-70mm f/2.8L IS USM','CANON-RF-2470L','24-70mm','f/2.8','Canon RF',56500000.00,10,'https://media.ldlc.com/r1600/ld/products/00/05/91/14/LD0005911492_1.jpg','<h3><strong>1. Tổng quan về Canon RF 24-70mm f/2.8L IS USM</strong></h3>\n<p>Ống kính <strong>Canon RF 24-70mm f/2.8L IS USM</strong> là một kiệt tác thực sự đến từ thương hiệu máy ảnh và ống kính hàng đầu thế giới Canon. Được chế tác với độ hoàn thiện không thể chê vào đâu được, sản phẩm này ra đời để làm hài lòng cả những nhiếp ảnh gia và nhà quay phim chuyên nghiệp khó tính nhất. Nó mang trong mình những công nghệ quang học tiên tiến nhất ở thời điểm hiện tại, đem đến một sức mạnh vượt trội giúp bạn ghi lại mọi khoảnh khắc với độ chính xác và chất lượng hình ảnh đáng kinh ngạc.</p>\n<h3><strong>2. Cấu trúc quang học và Độ sắc nét</strong></h3>\n<p>Trái tim của <strong>Canon RF 24-70mm f/2.8L IS USM</strong> nằm ở hệ thống quang học vô cùng tinh vi. Với sự kết hợp của các thấu kính phi cầu đặc biệt (Aspherical) và các thấu kính tán xạ thấp (ED/Super ED), ống kính này triệt tiêu gần như hoàn toàn hiện tượng quang sai màu, viền tím và méo hình. Dù bạn chụp ở trung tâm hay sát rìa bức ảnh, độ phân giải vẫn được duy trì ở mức tối đa.</p>\n<p>Thêm vào đó, lớp phủ độc quyền của Canon giúp ngăn chặn triệt để hiện tượng bóng ma (ghosting) và lóa sáng (flare), ngay cả khi bạn phải đối mặt trực tiếp với nguồn sáng mạnh. Điều này mang lại độ tương phản tuyệt vời và màu sắc sống động, chân thực đến từng chi tiết nhỏ nhất.</p>\n<h3><strong>3. Hiệu năng Lấy nét tự động (AF) siêu tốc</strong></h3>\n<p>Được trang bị hệ thống motor lấy nét tuyến tính thế hệ mới nhất, ống kính phản hồi cực kỳ nhanh chóng và êm ái. Hệ thống AF không chỉ lấy nét chớp nhoáng mà còn theo dõi chủ thể cực kỳ chính xác. Dù bạn đang chụp ảnh thể thao với tốc độ chuyển động chóng mặt, hay quay những thước phim điện ảnh yêu cầu độ mượt mà tuyệt đối, <strong>Canon RF 24-70mm f/2.8L IS USM</strong> đều đáp ứng một cách xuất sắc mà không gây ra bất kỳ tiếng ồn cơ học nào.</p>\n<h3><strong>4. Thiết kế công thái học và Độ bền bỉ</strong></h3>\n<p>Bất chấp việc sở hữu sức mạnh quang học khủng, ống kính lại có một thiết kế vô cùng cân đối và vừa vặn khi gắn lên thân máy. Vỏ ngoài được chế tạo từ hợp kim cao cấp không chỉ giúp giảm tối đa trọng lượng mà còn mang lại cảm giác cầm nắm đầm tay, chắc chắn.</p>\n<p>Đặc biệt, hệ thống ron cao su bảo vệ được bố trí tỉ mỉ ở mọi khớp nối và nút bấm, giúp ống kính có khả năng chống bụi và chống nước văng cực tốt. Lớp phủ Fluorine ở thấu kính phía trước còn giúp bạn dễ dàng lau chùi nước, dầu mỡ hay dấu vân tay, bảo vệ ống kính an toàn trong những môi trường làm việc khắc nghiệt nhất.</p>\n<h3><strong>5. Khả năng sáng tạo không giới hạn</strong></h3>\n<p>Với thông số tiêu cự 24-70mm và khẩu độ lớn f/2.8, bạn nắm trong tay khả năng kiểm soát độ sâu trường ảnh tuyệt đối. Hãy tưởng tượng những bức ảnh chân dung với chủ thể sắc nét đến từng sợi tóc, nổi bật hoàn toàn trên một phông nền được làm mờ (bokeh) mềm mại như nhung. Hoặc khả năng bắt sáng tuyệt vời giúp bạn tự tin chụp ảnh trong điều kiện ánh sáng cực yếu mà không cần tăng ISO lên mức nhiễu hạt.</p>\n<p>Từ chụp ảnh phong cảnh bao la, kiến trúc hùng vĩ, nhiếp ảnh đường phố đời thường cho đến những sự kiện lộng lẫy, <strong>Canon RF 24-70mm f/2.8L IS USM</strong> không chỉ là một công cụ, mà là người bạn đồng hành truyền cảm hứng bất tận để bạn vượt qua mọi giới hạn của sự sáng tạo.</p>\n','Canon',NULL,'[{\"url\":\"https:\\/\\/png.pngtree.com\\/background\\/20230403\\/original\\/pngtree-aurora-borealis-on-night-sky-over-winter-landscape-with-snow-aurora-picture-image_2294003.jpg\",\"cap\":\"Chi ti\\u1ebft ng\\u00e0m\"},{\"url\":\"https:\\/\\/m.yodycdn.com\\/blog\\/phong-canh-dep-o-viet-nam-yody-vn-13.jpg\",\"cap\":\"M\\u1eb7t b\\u00ean tr\\u00e1i\"},{\"url\":\"https:\\/\\/th.bing.com\\/th\\/id\\/R.3549f07ff08d2a84ef6ad5eb6f24e6af?rik=m%2f9HNszy6tMXhA&pid=ImgRaw&r=0\",\"cap\":\"G\\u00f3c nh\\u00ecn ch\\u00ednh di\\u1ec7n\"},{\"url\":\"https:\\/\\/imgt.taimienphi.vn\\/cf\\/Images\\/dip\\/2023\\/10\\/13\\/anh-hoang-hon-6.jpg\",\"cap\":\"Th\\u1ea5u k\\u00ednh tr\\u01b0\\u1edbc\"},{\"url\":\"https:\\/\\/scr.vn\\/wp-content\\/uploads\\/2020\\/08\\/H%C3%ACnh-c%E1%BA%A3nh-ho%C3%A0ng-h%C3%B4n-%C4%91%E1%BA%B9p-4k-scaled.jpg\",\"cap\":\"G\\u00f3c t\\u1eeb tr\\u00ean xu\\u1ed1ng\"},{\"url\":\"https:\\/\\/www.migolatravel.com\\/wp-content\\/uploads\\/2019\\/05\\/bac-cuc-3-1.jpg\",\"cap\":\"G\\u00f3c 45 \\u0111\\u1ed9\"}]','[{\"url\":\"https:\\/\\/mia.vn\\/media\\/uploads\\/blog-du-lich\\/du-lich-bac-cuc-6-1728749566.jpg\",\"tag\":\"Th\\u00e0nh ph\\u1ed1\",\"text\":\"Ch\\u1ee5p c\\u1eadn c\\u1ea3nh chi ti\\u1ebft\"},{\"url\":\"https:\\/\\/vphoto.vietnam.vn\\/thumb\\/1200x675\\/vietnam\\/resource\\/IMAGE\\/2026\\/09\\/17\\/1789619523936_anh-man-hinh-2026-09-17-luc-11-31-09.png\",\"tag\":\"C\\u1ef1c quang\",\"text\":\"\\u00c1nh s\\u00e1ng v\\u00e0 b\\u00f3ng t\\u1ed1i h\\u00f2a quy\\u1ec7n\"},{\"url\":\"https:\\/\\/datviettour.com.vn\\/uploads\\/images\\/tin-tuc-SEO-chau-au\\/tong-hop\\/danh-thang\\/bac-cuc-quang-day-mau-sac.jpg\",\"tag\":\"\\u0110\\u1ed9ng v\\u1eadt hoang d\\u00e3\",\"text\":\"S\\u1eafc m\\u00e0u tuy\\u1ec7t \\u0111\\u1eb9p trong \\u0111\\u00eam\"},{\"url\":\"https:\\/\\/bocapvang.net\\/wp-content\\/uploads\\/2022\\/07\\/phong-canh-dep-o-viet-nam-8.jpg.crdownload.jpg\",\"tag\":\"Street Photography\",\"text\":\"B\\u1ee9c \\u1ea3nh mang \\u0111\\u1ea7y c\\u1ea3m x\\u00fac\"},{\"url\":\"https:\\/\\/media.vietravel.com\\/images\\/Content\\/du-lich-bac-cuc-4.png\",\"tag\":\"Ch\\u00e2n dung ngh\\u1ec7 thu\\u1eadt\",\"text\":\"Kho\\u1ea3nh kh\\u1eafc kh\\u00f3 qu\\u00ean\"}]','in_stock','2026-08-15 00:33:07','2026-09-29 10:20:44'),(5,2,'Canon RF 50mm f/1.2L USM','CANON-RF-50F12L','50mm','f/1.2','Canon RF',54900000.00,7,'https://www.abesofmaine.com/files/AB/product/extra/large/canon_rf_50mm_f_1_2l_usm_lens_11110.jpg','<h3><strong>1. Tổng quan về Canon RF 50mm f/1.2L USM</strong></h3>\n<p>Ống kính <strong>Canon RF 50mm f/1.2L USM</strong> là một kiệt tác thực sự đến từ thương hiệu máy ảnh và ống kính hàng đầu thế giới Canon. Được chế tác với độ hoàn thiện không thể chê vào đâu được, sản phẩm này ra đời để làm hài lòng cả những nhiếp ảnh gia và nhà quay phim chuyên nghiệp khó tính nhất. Nó mang trong mình những công nghệ quang học tiên tiến nhất ở thời điểm hiện tại, đem đến một sức mạnh vượt trội giúp bạn ghi lại mọi khoảnh khắc với độ chính xác và chất lượng hình ảnh đáng kinh ngạc.</p>\n<h3><strong>2. Cấu trúc quang học và Độ sắc nét</strong></h3>\n<p>Trái tim của <strong>Canon RF 50mm f/1.2L USM</strong> nằm ở hệ thống quang học vô cùng tinh vi. Với sự kết hợp của các